#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;

// Soma dos j menores valores disponiveis: A + (A+1) + ... + (A+j-1)
// = j*A + j*(j-1)/2  (menor soma parcial possivel apos j rodadas)
static inline lll minSum(ll j, ll A){
    return (lll)A * j + (lll)j * (j - 1) / 2;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int P;
    if(!(cin >> P)) return 0;
    while(P--){
        ll L, A, B;
        cin >> L >> A >> B;
        ll N = B - A + 1; // quantidade de valores distintos disponiveis em [A,B]

        // Estrategia otima: usar os menores valores primeiro.
        // A soma parcial apos j rodadas e sempre >= minSum(j, A).
        // O jogo termina na primeira rodada em que a soma atinge L,
        // ou por esgotamento dos N valores distintos.

        // Encontrar o menor j0 com minSum(j0, A) >= L  (via doubling + busca binaria)
        ll lo = 1, hi = 1;
        while(minSum(hi, A) < (lll)L) hi <<= 1;
        while(lo < hi){
            ll mid = lo + ((hi - lo) >> 1);
            if(minSum(mid, A) >= (lll)L) hi = mid;
            else lo = mid + 1;
        }

        // Se minSum(N, A) < L, entao j0 > N e o jogo acaba por esgotamento: N rodadas.
        // Caso contrario, o maximo de rodadas e exatamente j0 (atingivel com A, A+1, ...).
        ll ans = (N < lo) ? N : lo;
        cout << ans << '\n';
    }
    return 0;
}
